"use client";

/**
 * Recording shot: the treatment that turns a raw screen recording into a shot.
 * It crops the capture, fits it to the frame, trims its start, and moves a
 * camera over it from keyframes, never showing an empty edge.
 *
 * Written by Better Design. Painted from the theme prop; with no recording it
 * shows a placeholder browser page drawn from the same tokens.
 */
import { AbsoluteFill, Img, OffthreadVideo, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, progress, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const VIDEO = /\.(mp4|webm|mov)(\?.*)?$/i;
const DEFAULT_MOVE = 24;

/** One camera move, eased from wherever the camera stands when it starts. */
export interface CameraMove {
  /** Frame on the composition's clock the move starts. */
  from: number;
  /** Frames the move takes. Defaults to 24. */
  frames?: number;
  /** Magnification. 1 is the fitted shot. */
  scale?: number;
  /** The point to hold in the centre, as [across, down] fractions of the frame. */
  focus?: [number, number];
}

/** The part of the capture to keep, as fractions of its width and height. */
export interface CaptureRegion {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface RecordingShotProps {
  /** A screen recording (.mp4, .webm, .mov) or a still. Drawn as a placeholder page when absent. */
  recording?: string;
  /** The capture's pixel size, as ffprobe reports it. Defaults to 1440 by 900, a common laptop capture. */
  captureSize?: { width: number; height: number };
  /** The part of the capture to show. Defaults to all of it. */
  keep?: CaptureRegion;
  /** "fill" covers the frame; "whole" shows the whole kept region on the theme background. */
  framing?: "fill" | "whole";
  /** Frames into the recording where the shot starts. */
  startAt?: number;
  /** Camera moves. Omit for a gentle push in and back out. */
  camera?: CameraMove[];
  /** Corner radius of the framed capture, in pixels. */
  corner?: number;
  /** Fade the shot in over its first 16 frames. */
  fadeIn?: boolean;
  theme?: Partial<VideoTheme>;
}

interface Pose {
  zoom: number;
  x: number;
  y: number;
}

const REST: Pose = { zoom: 1, x: 0.5, y: 0.5 };
const WHOLE: CaptureRegion = { x: 0, y: 0, width: 1, height: 1 };
const DEFAULT_CAMERA: CameraMove[] = [
  { from: 20, frames: 30, scale: 1.4, focus: [0.72, 0.52] },
  { from: 90, frames: 30, scale: 1 },
];

/** The pose at `frame`: the last started move, eased from wherever the camera stood when it began. */
function poseAt(frame: number, moves: CameraMove[]): Pose {
  let index = -1;
  for (let i = 0; i < moves.length; i++) if (moves[i].from <= frame) index = i;
  if (index < 0) return REST;
  const move = moves[index];
  const from = poseAt(move.from - 0.001, moves.slice(0, index));
  const to: Pose = { zoom: Math.max(1, move.scale ?? from.zoom), x: move.focus?.[0] ?? from.x, y: move.focus?.[1] ?? from.y };
  const t = easings.inOut(progress(frame, move.from, move.frames ?? DEFAULT_MOVE));
  return { zoom: from.zoom + (to.zoom - from.zoom) * t, x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t };
}

function PlaceholderPage({ theme }: { theme: VideoTheme }) {
  const bar = (w: string, h: number, c = withAlpha(theme.foreground, 0.12)) => <div style={{ width: w, height: h, borderRadius: h / 2, background: c }} />;
  return (
    <div style={{ position: "absolute", inset: 0, background: theme.background, display: "flex", flexDirection: "column" }}>
      <div style={{ height: "10%", display: "flex", alignItems: "flex-end", paddingBottom: "1.6%", gap: 14, padding: "0 2%", background: theme.muted, borderBottom: `1px solid ${theme.border}` }}>
        {[0, 1, 2].map((i) => (
          <div key={i} style={{ width: 14, height: 14, borderRadius: 7, background: withAlpha(theme.foreground, 0.16) }} />
        ))}
        <div style={{ marginLeft: "18%", width: "36%", height: "52%", borderRadius: 999, background: theme.card, border: `1px solid ${theme.border}` }} />
      </div>
      <div style={{ flex: 1, display: "flex", padding: "4% 6%", gap: "5%" }}>
        <div style={{ flex: 1.1, display: "flex", flexDirection: "column", justifyContent: "center", gap: 26 }}>
          {bar("30%", 18, withAlpha(theme.primary, 0.5))}
          {bar("92%", 54, withAlpha(theme.foreground, 0.82))}
          {bar("70%", 54, withAlpha(theme.foreground, 0.82))}
          {bar("80%", 18)}
          {bar("64%", 18)}
          <div style={{ display: "flex", gap: 18, marginTop: 20 }}>
            <div style={{ width: 220, height: 64, borderRadius: 32, background: theme.primary }} />
            <div style={{ width: 180, height: 64, borderRadius: 32, border: `2px solid ${theme.border}` }} />
          </div>
        </div>
        <div style={{ flex: 1, borderRadius: 24, background: theme.card, border: `1px solid ${theme.border}`, padding: 36, display: "flex", flexDirection: "column", gap: 26, alignSelf: "center", height: "78%" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            {bar("38%", 18, withAlpha(theme.foreground, 0.7))}
            <div style={{ width: 90, height: 34, borderRadius: 17, background: theme.accent }} />
          </div>
          <div style={{ flex: 1, display: "flex", alignItems: "flex-end", gap: 16, paddingBottom: 6, borderBottom: `1px solid ${theme.border}` }}>
            {[0.38, 0.52, 0.46, 0.68, 0.6, 0.84, 0.74].map((h, i) => (
              <div key={i} style={{ flex: 1, height: `${h * 100}%`, borderRadius: 10, background: i === 5 ? theme.primary : withAlpha(theme.primary, 0.2) }} />
            ))}
          </div>
          {[0.6, 0.44].map((w, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 18 }}>
              <div style={{ width: 40, height: 40, borderRadius: 12, background: i === 0 ? withAlpha(theme.primary, 0.2) : theme.muted }} />
              {bar(`${w * 100}%`, 14, withAlpha(theme.foreground, 0.55))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/** A screen recording cropped, fitted and framed by a keyframed camera. */
export function RecordingShot({
  recording,
  captureSize = { width: 1440, height: 900 },
  keep = WHOLE,
  framing = "fill",
  startAt = 0,
  camera = DEFAULT_CAMERA,
  corner = 0,
  fadeIn = true,
  theme: themeOverride,
}: RecordingShotProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();

  // The kept region of the source and the box it fits into.
  const left = keep.x;
  const top = keep.y;
  const keepW = Math.max(0.01, Math.min(keep.width, 1 - left));
  const keepH = Math.max(0.01, Math.min(keep.height, 1 - top));
  const keptAspect = (captureSize.width * keepW) / (captureSize.height * keepH);
  const wider = keptAspect > W / H;
  const fitWidth = framing === "fill" ? !wider : wider;
  const boxW = fitWidth ? W : H * keptAspect;
  const boxH = fitWidth ? W / keptAspect : H;
  const mediaW = boxW / keepW;
  const mediaH = boxH / keepH;

  // Camera: scale about the focal point, then clamp so the layer always covers the frame.
  const pose = poseAt(frame, [...camera].sort((a, b) => a.from - b.from));
  const s = pose.zoom;
  const tx = Math.min(0, Math.max(W - W * s, W / 2 - pose.x * W * s));
  const ty = Math.min(0, Math.max(H - H * s, H / 2 - pose.y * H * s));

  const enter = fadeIn ? easings.out(progress(frame, 0, 16)) : 1;
  const mediaStyle = { width: "100%", height: "100%", objectFit: "cover" as const, display: "block" };

  const media = recording ? (
    VIDEO.test(recording) ? (
      <OffthreadVideo src={srcOf(recording)} muted trimBefore={startAt} style={mediaStyle} />
    ) : (
      <Img src={srcOf(recording)} style={mediaStyle} />
    )
  ) : (
    <PlaceholderPage theme={theme} />
  );

  return (
    <AbsoluteFill style={{ background: theme.background, overflow: "hidden", transform: `scale(${0.985 + enter * 0.015})` }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: W,
          height: H,
          transformOrigin: "0 0",
          transform: `translate(${tx}px, ${ty}px) scale(${s})`,
          opacity: enter,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: (W - boxW) / 2,
            top: (H - boxH) / 2,
            width: boxW,
            height: boxH,
            borderRadius: corner,
            overflow: "hidden",
          }}
        >
          <div style={{ position: "absolute", left: -left * mediaW, top: -top * mediaH, width: mediaW, height: mediaH }}>{media}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
